const QDRANT_URL = 'http://qdrant:6333';
const QDRANT_API_KEY = process.env.QDRANT_API_KEY || '';
const OLLAMA_URL = 'http://host.docker.internal:11434';

async function qdrantScroll(collection, filter, limit=100) {
  const body = {limit, with_payload: true, with_vector: false};
  if (filter) body.filter = filter;
  const r = await fetch(`${QDRANT_URL}/collections/${collection}/points/scroll`, {
    method: 'POST', headers: {'api-key': QDRANT_API_KEY, 'Content-Type': 'application/json'},
    body: JSON.stringify(body)
  });
  const d = await r.json();
  return d.result?.points || [];
}

async function qdrantStore(collection, id, vector, payload) {
  await fetch(`${QDRANT_URL}/collections/${collection}/points`, {
    method: 'PUT', headers: {'api-key': QDRANT_API_KEY, 'Content-Type': 'application/json'},
    body: JSON.stringify({points: [{id, vector, payload}]})
  });
}

async function qdrantUpdate(collection, ids, payload) {
  await fetch(`${QDRANT_URL}/collections/${collection}/points/payload`, {
    method: 'POST', headers: {'api-key': QDRANT_API_KEY, 'Content-Type': 'application/json'},
    body: JSON.stringify({payload, points: ids})
  });
}

async function embed(text) {
  const r = await fetch(`${OLLAMA_URL}/api/embed`, {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({model: 'nomic-embed-text', input: text})
  });
  const d = await r.json();
  return d.embeddings?.[0] || null;
}

function uuid() { return crypto.randomUUID(); }

// Fetch all audit events from past 30 days
const now = new Date();
const thirtyDaysAgo = new Date(now.getTime() - 30*24*60*60*1000).toISOString();
const events = await qdrantScroll('audit_log', null, 5000);
const recent = events.filter(e => (e.payload?.timestamp || '') >= thirtyDaysAgo);

// Count by action type
const actionCounts = {};
for (const e of recent) {
  const action = e.payload?.action || 'unknown';
  actionCounts[action] = (actionCounts[action] || 0) + 1;
}

// Simple compliance score: percentage of governed action types present
const governedActions = ['store', 'recall', 'classify', 'POLICY_DENY', 'TRUST_DENY', 'DATA_CLASSIFICATION',
  'episode_start', 'episode_complete', 'learning_store', 'procedure_capture', 'benchmark_record', 'expire'];
const presentActions = governedActions.filter(a => actionCounts[a] > 0);
const score = Math.round((presentActions.length / governedActions.length) * 100);

// Store report
const reportId = uuid();
const vec = await embed('monthly compliance report score ' + score);
if (vec) {
  await qdrantStore('compliance_trends', reportId, vec, {
    report_id: reportId, generated_at: now.toISOString(),
    period_start: thirtyDaysAgo, period_end: now.toISOString(),
    total_events: recent.length, action_breakdown: actionCounts,
    compliance_score: score, governed_actions_present: presentActions,
    governed_actions_missing: governedActions.filter(a => !actionCounts[a])
  });
}

// Also log to audit
const auditVec = await embed('compliance report generated score ' + score);
if (auditVec) {
  await qdrantStore('audit_log', uuid(), auditVec, {
    action: 'compliance_report_generated', timestamp: now.toISOString(),
    details: {score, events: recent.length, missing: governedActions.filter(a => !actionCounts[a])},
    sensitivity: 'internal', project: 'global'
  });
}

return [{json: {score, total_events: recent.length, actions: Object.keys(actionCounts).length, missing: governedActions.filter(a => !actionCounts[a])}}];
